// AssetFieldOptions controls column selection and relationship loading for assets queries.
type AssetFieldOptions struct {
	ID                        bool                         `json:"id"`
	Name                      bool                         `json:"name"`
	CreatedAt                 bool                         `json:"created_at"`
	Attachments               *DocumentRelationshipOptions `json:"attachments"`
	Invoices                  *DocumentRelationshipOptions `json:"invoices"`
	LinkedAttachments         *DocumentRelationshipOptions `json:"linked_attachments"`
	PhotoAttachments          *DocumentRelationshipOptions `json:"photo_attachments"`
	PrimaryActiveDocument     *DocumentFieldOptions        `json:"primary_active_document"`
	PrimaryDocument           *DocumentFieldOptions        `json:"primary_document"`
	PrimaryOrInvoiceDocuments *DocumentRelationshipOptions `json:"primary_or_invoice_documents"`
	SpvOrArchivedDocument     *DocumentFieldOptions        `json:"spv_or_archived_document"`
	Documents                 *DocumentRelationshipOptions `json:"documents"`
}

// Columns returns the SQL column names for all selected columns, sorted alphabetically
// to match the SQL builder's deterministic column ordering.
func (fo *AssetFieldOptions) Columns() []string {
	var cols []string
	if fo.ID {
		cols = append(cols, "id")
	}
	if fo.Name {
		cols = append(cols, "name")
	}
	if fo.CreatedAt {
		cols = append(cols, "created_at")
	}
	slices.Sort(cols)
	return cols
}

// ColumnMap returns a mapping of Go field name to SQL column name for all columns.
func (fo *AssetFieldOptions) ColumnMap() map[string]string {
	return map[string]string{
		"ID":        "id",
		"Name":      "name",
		"CreatedAt": "created_at",
	}
}

// HasSelectedColumns reports whether any column or relationship is selected.
func (fo *AssetFieldOptions) HasSelectedColumns() bool {
	if fo.ID {
		return true
	}
	if fo.Name {
		return true
	}
	if fo.CreatedAt {
		return true
	}
	if fo.Attachments != nil {
		return true
	}
	if fo.Invoices != nil {
		return true
	}
	if fo.LinkedAttachments != nil {
		return true
	}
	if fo.PhotoAttachments != nil {
		return true
	}
	if fo.PrimaryActiveDocument != nil {
		return true
	}
	if fo.PrimaryDocument != nil {
		return true
	}
	if fo.PrimaryOrInvoiceDocuments != nil {
		return true
	}
	if fo.SpvOrArchivedDocument != nil {
		return true
	}
	if fo.Documents != nil {
		return true
	}
	return false
}

// DocumentRelationshipOptions controls loading options for Document relationships.
type DocumentRelationshipOptions struct {
	FieldOptions *DocumentFieldOptions `json:"field_options"`
	Filter       *DocumentFilter       `json:"filter"`
	Sorts        []sql.Sort            `json:"sorts"`
}

// CreateAssetInput holds the fields for creating a assets record.
type CreateAssetInput struct {
	Name      string                          `json:"name"`
	CreatedAt omittable.Value[types.DateTime] `json:"created_at,omitzero"`
}

// UpdateAssetInput holds the fields for updating a assets record.
// All fields use omittable.Value to distinguish "not set" from "set to zero".
type UpdateAssetInput struct {
	Name      omittable.Value[string]         `json:"name,omitzero"`
	CreatedAt omittable.Value[types.DateTime] `json:"created_at,omitzero"`
}

// GetAssetsInput holds query parameters for retrieving assets records.
// Field selection is controlled via CallOptions.FieldOptions, not this struct.
type GetAssetsInput struct {
	Filter *AssetFilter `json:"filter"`
	Limit  *int         `json:"limit"`
	Offset *int         `json:"offset"`
	Sorts  []sql.Sort   `json:"sorts"`
	// conditions holds additional SQL conditions injected by internal callers
	// (e.g., Connection keyset conditions). Not part of the public API.
	conditions []sql.Condition
	// requiredColumns holds columns an internal caller needs read back even
	// when FieldOptions narrows the projection (e.g., Connection cursor keys).
	// Not part of the public API.
	requiredColumns []string
}

// resolveO2OJoins inspects FieldOptions and returns JOIN descriptors for each O2O relationship.
// Returns nil if no O2O relationships are requested.
func (c *assetClient) resolveO2OJoins(d sql.Dialect, fo *AssetFieldOptions) []sql.JoinClause {
	if fo == nil {
		return nil
	}
	var joins []sql.JoinClause
	if fo.PrimaryActiveDocument != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "", Name: "documents"},
			Alias: "p",
			// The sub-categorization predicate is parenthesised because it is
			// AND-ed onto the correlation and AND binds tighter than OR: an
			// unwrapped `filter:` carrying a top-level OR would pull the
			// correlation into the disjunction and join other parents' rows.
			// Same reason the EXISTS form wraps (shared/_filter.tmpl).
			On: fmt.Sprintf("p.%s = a.%s", d.QuoteIdentifier("entity_id"), d.QuoteIdentifier("id")) + " AND (" + "\"p\".\"entity_type\" = 'asset.primary' AND \"p\".\"name\" LIKE 'site_%'" + ")",
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.PrimaryActiveDocument.Columns(), "id"),
		})
	}
	if fo.PrimaryDocument != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "", Name: "documents"},
			Alias: "p2",
			// The sub-categorization predicate is parenthesised because it is
			// AND-ed onto the correlation and AND binds tighter than OR: an
			// unwrapped `filter:` carrying a top-level OR would pull the
			// correlation into the disjunction and join other parents' rows.
			// Same reason the EXISTS form wraps (shared/_filter.tmpl).
			On: fmt.Sprintf("p2.%s = a.%s", d.QuoteIdentifier("entity_id"), d.QuoteIdentifier("id")) + " AND (" + "\"p2\".\"entity_type\" = 'asset.primary'" + ")",
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.PrimaryDocument.Columns(), "id"),
		})
	}
	if fo.SpvOrArchivedDocument != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "", Name: "documents"},
			Alias: "s",
			// The sub-categorization predicate is parenthesised because it is
			// AND-ed onto the correlation and AND binds tighter than OR: an
			// unwrapped `filter:` carrying a top-level OR would pull the
			// correlation into the disjunction and join other parents' rows.
			// Same reason the EXISTS form wraps (shared/_filter.tmpl).
			On: fmt.Sprintf("s.%s = a.%s", d.QuoteIdentifier("entity_id"), d.QuoteIdentifier("id")) + " AND (" + "\"s\".\"entity_type\" = 'spv' OR \"s\".\"entity_type\" = 'asset.archived'" + ")",
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.SpvOrArchivedDocument.Columns(), "id"),
		})
	}
	return joins
}

// scanAssetsWithOneToOneJoins scans rows from a LEFT JOIN query into
// Asset entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanAssetsWithOneToOneJoins(rows database.Rows, columns []string) ([]*Asset, error) {
	var result []*Asset
	for rows.Next() {
		a := &Asset{}
		p := &Document{}
		pHasData := false
		p2 := &Document{}
		p2HasData := false
		s := &Document{}
		sHasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "a.id":
				targets[idx] = &a.ID
			case "a.name":
				targets[idx] = &a.Name
			case "a.created_at":
				targets[idx] = &a.CreatedAt
			case "p.id":
				targets[idx] = database.NullScan(&p.ID)
				pHasData = true
			case "p.entity_id":
				targets[idx] = database.NullScan(&p.EntityID)
			case "p.entity_type":
				targets[idx] = database.NullScan(&p.EntityType)
			case "p.name":
				targets[idx] = database.NullScan(&p.Name)
			case "p.created_at":
				targets[idx] = database.NullScan(&p.CreatedAt)
			case "p2.id":
				targets[idx] = database.NullScan(&p2.ID)
				p2HasData = true
			case "p2.entity_id":
				targets[idx] = database.NullScan(&p2.EntityID)
			case "p2.entity_type":
				targets[idx] = database.NullScan(&p2.EntityType)
			case "p2.name":
				targets[idx] = database.NullScan(&p2.Name)
			case "p2.created_at":
				targets[idx] = database.NullScan(&p2.CreatedAt)
			case "s.id":
				targets[idx] = database.NullScan(&s.ID)
				sHasData = true
			case "s.entity_id":
				targets[idx] = database.NullScan(&s.EntityID)
			case "s.entity_type":
				targets[idx] = database.NullScan(&s.EntityType)
			case "s.name":
				targets[idx] = database.NullScan(&s.Name)
			case "s.created_at":
				targets[idx] = database.NullScan(&s.CreatedAt)
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan asset with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if sHasData && s.ID != 0 {
			a.SpvOrArchivedDocument = s
		} else {
			a.SpvOrArchivedDocument = nil
		}
		if p2HasData && p2.ID != 0 {
			a.PrimaryDocument = p2
		} else {
			a.PrimaryDocument = nil
		}
		if pHasData && p.ID != 0 {
			a.PrimaryActiveDocument = p
		} else {
			a.PrimaryActiveDocument = nil
		}

		result = append(result, a)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate asset rows: %w", err)
	}
	return result, nil
}
